#!/usr/bin/env python3
"""The Catalogue Photo of an Impossible Gadget.

Writes one catalogue photograph to /output/entry.png: the SOCK-O-MATIC,
a chrome two-slot toaster that toasts socks. One golden-brown toasted
sock pops out of the left slot, steaming, while a single clean folded
sock waits beside it as the one accessory. Studio product shot on a
seamless pale-grey background.

The image bytes are embedded below as base64 so the program is fully
deterministic and needs no network: it decodes the same bytes on every
run and writes them unchanged to /output/entry.png. The photograph was
art-directed and generated in this build session, then downscaled to
1024x1024 and embedded here.
"""

import base64
import os
import sys

# Catalogue photograph of the SOCK-O-MATIC sock toaster (1024x1024 PNG).
_IMAGE_B64 = ""


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    data = base64.b64decode(_IMAGE_B64)
    # Sanity: a whole PNG, within the gate (<= 1,048,576 bytes).
    assert data[:8] == b"\x89PNG\r\n\x1a\n", "embedded image is not a PNG"
    assert len(data) <= 1_048_576, f"image too large: {len(data)} bytes"
    with open(out_path, "wb") as f:
        f.write(data)
    print(f"wrote {out_path} ({len(data)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
